sourcesContent:
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { 
  Bell, 
  Search, 
  Menu, 
  User, 
  Settings, 
  LogOut, 
  ChevronRight,
  Home,
  MessageSquare,
  ShoppingCart,
  Users,
  BarChart,
  FileText,
  Calendar,
  Database,
  Shield,
  HelpCircle,
  X,
  Zap,
  Package,
  Sparkles
} from 'lucide-react';

const TopBar = ({ toggleSidebar }) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showSearch, setShowSearch] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [searchResults, setSearchResults] = useState([]);
  const navigate = useNavigate();
  const location = useLocation();

  const notificationsRef = useRef(null);
  const userMenuRef = useRef(null);
  const searchRef = useRef(null);

  // Charger les notifications
  useEffect(() => {
    const mockNotifications = [
      { 
        id: 1, 
        title: 'Nouveau message', 
        message: 'Un client a laissé un message sur votre produit', 
        time: 'Il y a 5 min', 
        read: false, 
        type: 'message',
        icon: MessageSquare,
        color: 'from-blue-500 to-blue-400',
        priority: 'high'
      },
      { 
        id: 2, 
        title: 'Commande validée', 
        message: 'Commande #12345 a été traitée avec succès', 
        time: 'Il y a 30 min', 
        read: false, 
        type: 'order',
        icon: ShoppingCart,
        color: 'from-emerald-500 to-emerald-400',
        priority: 'medium'
      },
      { 
        id: 3, 
        title: 'Nouvel utilisateur', 
        message: 'Marie Dupont s\'est inscrite sur votre boutique', 
        time: 'Il y a 2h', 
        read: true, 
        type: 'user',
        icon: Users,
        color: 'from-purple-500 to-purple-400',
        priority: 'low'
      },
      { 
        id: 4, 
        title: 'Performance exceptionnelle', 
        message: 'Votre boutique a atteint un record de ventes aujourd\'hui', 
        time: 'Hier', 
        read: true, 
        type: 'system',
        icon: Zap,
        color: 'from-amber-500 to-amber-400',
        priority: 'medium'
      },
      { 
        id: 5, 
        title: 'Maintenance planifiée', 
        message: 'Mise à jour système prévue ce soir à minuit', 
        time: 'Hier', 
        read: true, 
        type: 'system',
        icon: Shield,
        color: 'from-neutral-500 to-neutral-400',
        priority: 'low'
      },
    ];
    setNotifications(mockNotifications);
    setUnreadCount(mockNotifications.filter(n => !n.read).length);
  }, []);

  // Gérer les clics en dehors des menus
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (notificationsRef.current && !notificationsRef.current.contains(event.target)) {
        setShowNotifications(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setShowUserMenu(false);
      }
      if (searchRef.current && !searchRef.current.contains(event.target) && !event.target.closest('form')) {
        setIsSearchFocused(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Simuler des résultats de recherche
  useEffect(() => {
    if (searchQuery.trim()) {
      const mockResults = [
        { id: 1, type: 'page', title: 'Tableau de bord', path: '/admin', icon: Home },
        { id: 2, type: 'page', title: 'Commandes', path: '/admin/orders', icon: ShoppingCart },
        { id: 3, type: 'page', title: 'Utilisateurs', path: '/admin/users', icon: Users },
        { id: 4, type: 'page', title: 'Analytique', path: '/admin/analytics', icon: BarChart },
        { id: 5, type: 'page', title: 'Paramètres', path: '/admin/settings', icon: Settings },
      ].filter(item => 
        item.title.toLowerCase().includes(searchQuery.toLowerCase())
      );
      setSearchResults(mockResults);
    } else {
      setSearchResults([]);
    }
  }, [searchQuery]);

  // Marquer tout comme lu
  const markAllAsRead = useCallback(() => {
    setNotifications(prev => prev.map(n => ({ ...n, read: true })));
    setUnreadCount(0);
    setShowNotifications(false);
  }, []);

  // Gérer la recherche
  const handleSearch = useCallback((e) => {
    e.preventDefault();
    if (searchQuery.trim() && searchResults.length > 0) {
      navigate(searchResults[0].path);
      setSearchQuery('');
      setShowSearch(false);
    }
  }, [searchQuery, searchResults, navigate]);

  // Raccourcis clavier
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Ctrl + K pour la recherche
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        setShowSearch(true);
        document.querySelector('input[type="search"]')?.focus();
      }
      // Échap pour fermer les menus
      if (e.key === 'Escape') {
        setShowNotifications(false);
        setShowUserMenu(false);
        setShowSearch(false);
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  const getPageTitle = () => {
    const path = location.pathname;
    const pageTitles = {
      '/admin': 'Tableau de bord',
      '/admin/users': 'Gestion des utilisateurs',
      '/admin/products': 'Gestion des produits',
      '/admin/orders': 'Commandes',
      '/admin/analytics': 'Analytique',
      '/admin/messages': 'Messages',
      '/admin/settings': 'Paramètres',
      '/admin/reports': 'Rapports',
      '/admin/calendar': 'Calendrier',
      '/admin/notifications': 'Notifications',
      '/admin/system': 'Système',
      '/admin/database': 'Base de données',
      '/admin/backup': 'Sauvegarde',
    };
    return pageTitles[path] || 'Tableau de bord';
  };

  const getBreadcrumbs = () => {
    const path = location.pathname;
    const segments = path.split('/').filter(s => s);

    if (segments.length === 0) return [{ label: 'Tableau de bord', path: '/' }];

    const breadcrumbMap = {
      'admin': { label: 'Tableau de bord', path: '/admin', icon: Home },
      'users': { label: 'Utilisateurs', path: '/admin/users', icon: Users },
      'products': { label: 'Produits', path: '/admin/products', icon: Package },
      'orders': { label: 'Commandes', path: '/admin/orders', icon: ShoppingCart },
      'analytics': { label: 'Analytique', path: '/admin/analytics', icon: BarChart },
      'messages': { label: 'Messages', path: '/admin/messages', icon: MessageSquare },
      'settings': { label: 'Paramètres', path: '/admin/settings', icon: Settings },
      'reports': { label: 'Rapports', path: '/admin/reports', icon: FileText },
      'calendar': { label: 'Calendrier', path: '/admin/calendar', icon: Calendar },
      'notifications': { label: 'Notifications', path: '/admin/notifications', icon: Bell },
      'system': { label: 'Système', path: '/admin/system', icon: Shield },
      'database': { label: 'Base de données', path: '/admin/database', icon: Database },
      'backup': { label: 'Sauvegarde', path: '/admin/backup', icon: Database },
    };

    const breadcrumbs = [];
    let currentPath = '';

    segments.forEach(segment => {
      currentPath += `/${segment}`;
      const crumb = breadcrumbMap[segment] || { label: segment, path: currentPath };
      breadcrumbs.push(crumb);
    });

    return breadcrumbs;
  };

  const pageTitle = getPageTitle();
  const breadcrumbs = getBreadcrumbs();

  return (
    <header className="sticky top-0 z-50 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl 
      border-b border-neutral-200/50 dark:border-neutral-800/50 transition-all duration-500">

      {/* Barre supérieure */}
      <div className="px-4 sm:px-6 lg:px-8 py-4">
        <div className="flex items-center justify-between">

          {/* Partie gauche */}
          <div className="flex items-center gap-3 sm:gap-4">
            {/* Bouton menu mobile */}
            <button
              onClick={toggleSidebar}
              className="lg:hidden p-2.5 rounded-xl hover:bg-neutral-100 dark:hover:bg-neutral-800 
                transition-all duration-300 hover:scale-105 active:scale-95"
              aria-label="Toggle sidebar"
            >
              <Menu className="h-5 w-5 text-neutral-700 dark:text-neutral-300" />
            </button>

            {/* Titre et fil d'Ariane */}
            <div className="min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <div className="h-2 w-2 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 animate-pulse" />
                <h1 className="text-xl sm:text-2xl font-bold text-neutral-900 dark:text-white truncate">
                  {pageTitle}
                </h1>
              </div>

              {/* Fil d'Ariane amélioré */}
              <div className="flex items-center gap-1.5 text-sm text-neutral-500 dark:text-neutral-400">
                <Home className="h-3.5 w-3.5" />
                {breadcrumbs.map((crumb, index) => (
                  <React.Fragment key={crumb.path}>
                    <ChevronRight className="h-3 w-3 mx-1" />
                    <button
                      onClick={() => navigate(crumb.path)}
                      className="hover:text-primary-600 dark:hover:text-primary-400 transition-colors 
                        flex items-center gap-1.5"
                    >
                      {crumb.icon && <crumb.icon className="h-3.5 w-3.5" />}
                      <span className="truncate">{crumb.label}</span>
                    </button>
                  </React.Fragment>
                ))}
              </div>
            </div>
          </div>

          {/* Partie droite */}
          <div className="flex items-center gap-2 sm:gap-3">

            {/* Bouton recherche mobile */}
            <button
              onClick={() => setShowSearch(true)}
              className="lg:hidden p-2.5 rounded-xl hover:bg-neutral-100 dark:hover:bg-neutral-800 
                transition-all duration-300 hover:scale-105"
              aria-label="Rechercher"
            >
              <Search className="h-5 w-5 text-neutral-700 dark:text-neutral-300" />
            </button>

            {/* Barre de recherche desktop */}
            <div className="relative hidden lg:block" ref={searchRef}>
              <form onSubmit={handleSearch} className="relative">
                <div className={`relative transition-all duration-500 ${
                  isSearchFocused ? 'w-96' : 'w-64'
                }`}>
                  <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 h-4 w-4 
                    text-neutral-400" />
                  <input
                    type="search"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    onFocus={() => setIsSearchFocused(true)}
                    placeholder="Rechercher... (Ctrl+K)"
                    className="w-full pl-12 pr-4 py-2.5 rounded-2xl bg-neutral-100/50 dark:bg-neutral-800/50 
                      backdrop-blur-sm border border-neutral-200/50 dark:border-neutral-700/50 
                      focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent 
                      text-neutral-900 dark:text-white placeholder-neutral-500 transition-all duration-300"
                  />
                  {searchQuery && (
                    <button
                      type="button"
                      onClick={() => setSearchQuery('')}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 p-1 
                        hover:bg-neutral-200 dark:hover:bg-neutral-700 rounded-lg"
                    >
                      <X className="h-4 w-4 text-neutral-400" />
                    </button>
                  )}
                </div>

                {/* Résultats de recherche */}
                {isSearchFocused && searchResults.length > 0 && (
                  <div className="absolute top-full mt-2 w-full bg-white dark:bg-neutral-800 
                    rounded-2xl shadow-2xl border border-neutral-200 dark:border-neutral-700 
                    overflow-hidden z-50 animate-scale-in">
                    <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
                      <p className="text-sm font-semibold text-neutral-700 dark:text-neutral-300">
                        Résultats ({searchResults.length})
                      </p>
                    </div>
                    <div className="max-h-80 overflow-y-auto">
                      {searchResults.map(result => {
                        const Icon = result.icon;
                        return (
                          <button
                            key={result.id}
                            onClick={() => {
                              navigate(result.path);
                              setSearchQuery('');
                              setIsSearchFocused(false);
                            }}
                            className="w-full px-4 py-3 flex items-center gap-3 hover:bg-neutral-50 
                              dark:hover:bg-neutral-700/50 transition-colors border-b border-neutral-100 
                              dark:border-neutral-700 last:border-b-0"
                          >
                            <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-primary-500/10 
                              to-secondary-500/10 flex items-center justify-center">
                              <Icon className="h-5 w-5 text-primary-600 dark:text-primary-400" />
                            </div>
                            <div className="text-left">
                              <p className="font-medium text-neutral-900 dark:text-white">
                                {result.title}
                              </p>
                              <p className="text-xs text-neutral-500">{result.path}</p>
                            </div>
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}
              </form>
            </div>

            {/* Notifications */}
            <div className="relative" ref={notificationsRef}>
              <button
                onClick={() => setShowNotifications(!showNotifications)}
                className="relative p-2.5 rounded-xl hover:bg-neutral-100 dark:hover:bg-neutral-800 
                  transition-all duration-300 hover:scale-105 active:scale-95 group"
                aria-label="Notifications"
              >
                <Bell className="h-5 w-5 text-neutral-700 dark:text-neutral-300 
                  group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors" />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 h-5 w-5 bg-gradient-to-r from-red-500 to-pink-500 
                    text-white text-xs rounded-full flex items-center justify-center animate-pulse">
                    {unreadCount}
                  </span>
                )}
              </button>

              {/* Dropdown Notifications */}
              {showNotifications && (
                <div className="absolute right-0 mt-2 w-96 bg-white dark:bg-neutral-800 rounded-2xl 
                  shadow-2xl border border-neutral-200 dark:border-neutral-700 z-50 animate-scale-in">
                  {/* En-tête */}
                  <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="font-bold text-lg text-neutral-900 dark:text-white flex items-center gap-2">
                        <Bell className="h-5 w-5 text-primary-600" />
                        Notifications
                      </h3>
                      <div className="flex items-center gap-2">
                        {unreadCount > 0 && (
                          <button
                            onClick={markAllAsRead}
                            className="text-xs px-3 py-1 rounded-lg bg-primary-500/10 text-primary-600 
                              dark:text-primary-400 hover:bg-primary-500/20 transition-colors"
                          >
                            Tout lire
                          </button>
                        )}
                        <button
                          onClick={() => setShowNotifications(false)}
                          className="p-1 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg"
                        >
                          <X className="h-4 w-4" />
                        </button>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-sm text-neutral-500">
                      <Sparkles className="h-3 w-3" />
                      {unreadCount > 0 
                        ? `${unreadCount} nouvelles notifications` 
                        : 'Toutes les notifications sont lues'}
                    </div>
                  </div>

                  {/* Liste des notifications */}
                  <div className="max-h-96 overflow-y-auto">
                    {notifications.length === 0 ? (
                      <div className="p-8 text-center">
                        <div className="h-16 w-16 mx-auto mb-4 rounded-full bg-neutral-100 
                          dark:bg-neutral-800 flex items-center justify-center">
                          <Bell className="h-8 w-8 text-neutral-400" />
                        </div>
                        <p className="text-neutral-500 dark:text-neutral-400 font-medium">
                          Aucune notification
                        </p>
                        <p className="text-sm text-neutral-400 mt-1">
                          Vous serez notifié ici de toute activité
                        </p>
                      </div>
                    ) : (
                      <div className="divide-y divide-neutral-100 dark:divide-neutral-700">
                        {notifications.map(notification => {
                          const Icon = notification.icon;
                          return (
                            <div
                              key={notification.id}
                              onClick={() => {
                                if (!notification.read) {
                                  setNotifications(prev => prev.map(n => 
                                    n.id === notification.id ? { ...n, read: true } : n
                                  ));
                                  setUnreadCount(prev => prev - 1);
                                }
                                setShowNotifications(false);
                              }}
                              className={`p-4 cursor-pointer transition-all duration-300 hover:scale-[1.02] 
                                ${!notification.read 
                                  ? 'bg-gradient-to-r from-blue-50/50 to-transparent dark:from-blue-900/10' 
                                  : ''
                                }`}
                            >
                              <div className="flex items-start gap-4">
                                {/* Icône */}
                                <div className={`h-12 w-12 rounded-xl bg-gradient-to-br ${notification.color} 
                                  flex items-center justify-center shadow-lg flex-shrink-0`}>
                                  <Icon className="h-6 w-6 text-white" />
                                </div>

                                {/* Contenu */}
                                <div className="flex-1 min-w-0">
                                  <div className="flex items-start justify-between mb-1">
                                    <h4 className="font-semibold text-neutral-900 dark:text-white">
                                      {notification.title}
                                    </h4>
                                    <span className="text-xs text-neutral-500 whitespace-nowrap">
                                      {notification.time}
                                    </span>
                                  </div>
                                  <p className="text-sm text-neutral-600 dark:text-neutral-300 mb-2">
                                    {notification.message}
                                  </p>
                                  <div className="flex items-center justify-between">
                                    <span className={`text-xs px-2 py-1 rounded-full ${
                                      notification.priority === 'high' 
                                        ? 'bg-red-500/10 text-red-600 dark:text-red-400'
                                        : notification.priority === 'medium'
                                        ? 'bg-amber-500/10 text-amber-600 dark:text-amber-400'
                                        : 'bg-neutral-500/10 text-neutral-600 dark:text-neutral-400'
                                    }`}>
                                      {notification.priority === 'high' ? 'Haute priorité' : 
                                       notification.priority === 'medium' ? 'Moyenne priorité' : 'Basse priorité'}
                                    </span>
                                    {!notification.read && (
                                      <div className="flex items-center gap-1 text-primary-600 text-xs">
                                        <div className="h-2 w-2 rounded-full bg-primary-500 animate-pulse" />
                                        Non lu
                                      </div>
                                    )}
                                  </div>
                                </div>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>

                  {/* Pied de page */}
                  <div className="p-3 border-t border-neutral-200 dark:border-neutral-700">
                    <button
                      onClick={() => {
                        navigate('/admin/notifications');
                        setShowNotifications(false);
                      }}
                      className="w-full py-2.5 text-sm text-primary-600 dark:text-primary-400 
                        hover:bg-neutral-50 dark:hover:bg-neutral-700 rounded-xl transition-colors 
                        font-medium flex items-center justify-center gap-2"
                    >
                      <Bell className="h-4 w-4" />
                      Voir toutes les notifications
                    </button>
                  </div>
                </div>
              )}
            </div>

            {/* Menu utilisateur */}
            <div className="relative" ref={userMenuRef}>
              <button
                onClick={() => setShowUserMenu(!showUserMenu)}
                className="flex items-center gap-3 group"
              >
                <div className="relative">
                  <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 
                    flex items-center justify-center shadow-lg group-hover:scale-110 transition-transform duration-300">
                    <User className="h-5 w-5 text-white" />
                  </div>
                  <div className="absolute -bottom-1 -right-1 h-4 w-4 rounded-full bg-emerald-500 
                    border-2 border-white dark:border-neutral-800"></div>
                </div>
                <div className="hidden lg:block text-left">
                  <p className="text-sm font-semibold text-neutral-900 dark:text-white group-hover:text-primary-600 
                    dark:group-hover:text-primary-400 transition-colors">
                    Enzo Admin
                  </p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400 flex items-center gap-1">
                    <Shield className="h-3 w-3" />
                    Super Admin
                  </p>
                </div>
                <ChevronRight className={`h-4 w-4 text-neutral-400 transition-transform duration-300 ${
                  showUserMenu ? 'rotate-90' : ''
                }`} />
              </button>

              {/* Dropdown User Menu */}
              {showUserMenu && (
                <div className="absolute right-0 mt-2 w-64 bg-white dark:bg-neutral-800 rounded-2xl 
                  shadow-2xl border border-neutral-200 dark:border-neutral-700 z-50 animate-scale-in">
                  {/* En-tête profil */}
                  <div className="p-4 border-b border-neutral-200 dark:border-neutral-700">
                    <div className="flex items-center gap-3 mb-3">
                      <div className="h-14 w-14 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 
                        flex items-center justify-center shadow-xl">
                        <User className="h-7 w-7 text-white" />
                      </div>
                      <div>
                        <p className="font-bold text-neutral-900 dark:text-white">Enzo Admin</p>
                        <p className="text-sm text-neutral-500 dark:text-neutral-400">enzo@gmail.com</p>
                        <div className="flex items-center gap-1 mt-1">
                          <div className="h-2 w-2 rounded-full bg-emerald-500"></div>
                          <span className="text-xs text-emerald-600 dark:text-emerald-400">En ligne</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Menu items */}
                  <div className="p-2">
                    <button
                      onClick={() => {
                        navigate('/admin/profile');
                        setShowUserMenu(false);
                      }}
                      className="w-full px-4 py-3 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-700/50 
                        transition-colors flex items-center gap-3 mb-1"
                    >
                      <div className="h-10 w-10 rounded-lg bg-blue-500/10 flex items-center justify-center">
                        <User className="h-5 w-5 text-blue-600 dark:text-blue-400" />
                      </div>
                      <div className="text-left">
                        <p className="font-medium text-neutral-900 dark:text-white">Mon profil</p>
                        <p className="text-xs text-neutral-500">Gérer vos informations</p>
                      </div>
                    </button>

                    <button
                      onClick={() => {
                        navigate('/admin/settings');
                        setShowUserMenu(false);
                      }}
                      className="w-full px-4 py-3 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-700/50 
                        transition-colors flex items-center gap-3 mb-1"
                    >
                      <div className="h-10 w-10 rounded-lg bg-purple-500/10 flex items-center justify-center">
                        <Settings className="h-5 w-5 text-purple-600 dark:text-purple-400" />
                      </div>
                      <div className="text-left">
                        <p className="font-medium text-neutral-900 dark:text-white">Paramètres</p>
                        <p className="text-xs text-neutral-500">Personnaliser l'interface</p>
                      </div>
                    </button>

                    <button
                      onClick={() => {
                        navigate('/admin/help');
                        setShowUserMenu(false);
                      }}
                      className="w-full px-4 py-3 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-700/50 
                        transition-colors flex items-center gap-3"
                    >
                      <div className="h-10 w-10 rounded-lg bg-amber-500/10 flex items-center justify-center">
                        <HelpCircle className="h-5 w-5 text-amber-600 dark:text-amber-400" />
                      </div>
                      <div className="text-left">
                        <p className="font-medium text-neutral-900 dark:text-white">Aide & Support</p>
                        <p className="text-xs text-neutral-500">Documentation et assistance</p>
                      </div>
                    </button>
                  </div>

                  {/* Séparateur */}
                  <div className="px-4 py-2">
                    <div className="border-t border-neutral-200 dark:border-neutral-700"></div>
                  </div>

                  {/* Déconnexion */}
                  <div className="p-2">
                    <button
                      onClick={() => {
                        localStorage.removeItem('authToken');
                        localStorage.removeItem('userData');
                        navigate('/login');
                        setShowUserMenu(false);
                      }}
                      className="w-full px-4 py-3 rounded-xl bg-gradient-to-r from-red-500/10 to-pink-500/10 
                        hover:from-red-500/20 hover:to-pink-500/20 transition-all duration-300 
                        flex items-center gap-3 group/btn"
                    >
                      <div className="h-10 w-10 rounded-lg bg-gradient-to-r from-red-500 to-pink-500 
                        flex items-center justify-center group-hover/btn:scale-110 transition-transform">
                        <LogOut className="h-5 w-5 text-white" />
                      </div>
                      <div className="text-left">
                        <p className="font-bold text-red-600 dark:text-red-400">Déconnexion</p>
                        <p className="text-xs text-red-500/70">Se déconnecter du système</p>
                      </div>
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Barre de recherche mobile overlay */}
      {showSearch && (
        <div className="lg:hidden fixed inset-0 bg-black/50 backdrop-blur-sm z-50 animate-fade-in">
          <div className="bg-white dark:bg-neutral-800 p-4">
            <div className="flex items-center gap-3 mb-4">
              <button
                onClick={() => setShowSearch(false)}
                className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg"
              >
                <X className="h-5 w-5" />
              </button>
              <form onSubmit={handleSearch} className="flex-1">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 
                    text-neutral-400" />
                  <input
                    type="search"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Rechercher..."
                    className="w-full pl-12 pr-4 py-3 rounded-xl bg-neutral-100 dark:bg-neutral-700 
                      border border-neutral-200 dark:border-neutral-600 focus:outline-none focus:ring-2 
                      focus:ring-primary-500 text-neutral-900 dark:text-white"
                    autoFocus
                  />
                </div>
              </form>
            </div>
            {searchResults.length > 0 && (
              <div className="bg-neutral-50 dark:bg-neutral-700 rounded-xl p-2">
                {searchResults.map(result => (
                  <button
                    key={result.id}
                    onClick={() => {
                      navigate(result.path);
                      setShowSearch(false);
                    }}
                    className="w-full p-3 rounded-lg hover:bg-white dark:hover:bg-neutral-600 
                      text-left flex items-center gap-3"
                  >
                    <result.icon className="h-5 w-5 text-primary-600" />
                    <span className="font-medium">{result.title}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </header>
  );
};

export default TopBar;
